<?php /** The balance strip of a draft (a courtesy; the trigger is the gate) with the Post button, which follows it (disabled while out of balance, no lines, no period or a closed period — the endpoint refuses anyway). Data: e, balance, oob?, may? (write) */
$ok = $balance['balances']; $closed = $e['period_status'] === 'closed'; $noPeriod = $e['period_id'] === null; $mayWrite = $may['write'] ?? has_right('journal.write'); $postable = $ok && !$closed && !$noPeriod; $title = $e['number'] ?? 'Draft #' . (int) $e['journal_entry_id']; ?>
<div id="entry-balance" <?= !empty($oob) ? 'hx-swap-oob="true"' : '' ?> class="card mb-3 border-<?= $ok ? 'success' : 'danger' ?>"><div class="card-body p-3 d-flex flex-wrap justify-content-between align-items-center gap-2">
    <div class="fs-12"><span class="text-muted">Debits</span> <span class="fw-semibold" id="entry-balance-debits"><?= e(fmt_money($balance['debits'], $e['currency'])) ?></span> <span class="text-muted ms-2">Credits</span> <span class="fw-semibold" id="entry-balance-credits"><?= e(fmt_money($balance['credits'], $e['currency'])) ?></span></div>
    <div><span class="badge bg-<?= $ok ? 'success' : 'danger' ?>" id="entry-balance-state"><?= $ok ? 'balances' : ((int) $balance['lines'] === 0 ? 'no lines' : 'out by ' . number_format(abs((float) $balance['difference']), 2)) ?></span>
        <?php if ($noPeriod): ?><span class="badge bg-soft-danger text-danger" id="entry-balance-period">no period</span><?php elseif ($closed): ?><span class="badge bg-dark" id="entry-balance-period"><?= e($e['period_name']) ?> closed</span><?php else: ?><span class="badge bg-<?= (int) $e['period_reopen_count'] > 0 ? 'warning text-dark' : 'success' ?>" id="entry-balance-period"><?= e($e['period_name']) ?></span><?php endif; ?></div>
    <?php if ($mayWrite && $e['status'] === 'draft'): ?>
    <form method="post" action="/journal/post.php" hx-post="/journal/post.php" hx-target="#flash" class="ms-auto" hx-confirm="Post <?= e($title) ?> into <?= e($e['period_name'] ?? 'its period') ?>? It never changes afterwards."><?= csrf_field() ?><input type="hidden" name="entry" value="<?= (int) $e['journal_entry_id'] ?>">
        <button type="submit" class="btn btn-primary btn-touch" id="entry-post-btn" <?= $postable ? '' : 'disabled' ?>>Post</button>
        <?php if (!$postable): ?><div class="fs-12 text-muted mt-1" id="entry-post-why"><?= (int) $balance['lines'] === 0 ? 'Add lines first.' : (!$ok ? 'It must balance first.' : ($noPeriod ? 'No fiscal period covers its date.' : 'Its period is closed.')) ?></div><?php endif; ?></form>
    <?php endif; ?>
</div></div>
